    /// <summary>A function decorated with @pytest.fixture: tests that name it as a parameter get its value.</summary>
    internal sealed class PyFixture
    {
        public readonly object? Func;
        public readonly string Scope;
        public readonly bool Autouse;
        public PyFixture(object? func, string scope, bool autouse) { Func = func; Scope = scope; Autouse = autouse; }
        public override string ToString() => $"<fixture {Builtins.__name_of(Func)}>";
    }

    /// <summary>A test function with pytest marks (parametrize, skip, xfail); called, it calls the function.</summary>
    internal sealed class PyTestMarks : PyClosure
    {
        public readonly object? Func;
        public readonly List<(string[] Names, List<object?[]> Rows, List<string>? Ids)> Parametrize = new List<(string[], List<object?[]>, List<string>?)>();
        public string? SkipReason;
        public bool Xfail;
        public string? XfailReason;
        PyTestMarks(object? func) : base(func == null ? "test" : Builtins.__name_of(func), (a, kw) => Builtins.__invoke_kw(func, a, kw)) { Func = func; }
        public static PyTestMarks Of(object? f) => f as PyTestMarks ?? new PyTestMarks(f);
    }

    /// <summary>pytest.fail(reason) / a failed pytest.raises.</summary>
    internal sealed class TestFailed : Exception { public TestFailed(string message) : base(message) { } }
    /// <summary>pytest.skip(reason) inside a test.</summary>
    internal sealed class TestSkipped : Exception { public TestSkipped(string message) : base(message) { } }

    /// <summary>What pytest.raises(...) as excinfo gives: the exception raised in the block.</summary>
    internal sealed class ExceptionInfo
    {
        public dynamic? value;
        public Type? type;
        public bool match(string pattern) =>
            Regex.IsMatch(Builtins.str(value), pattern) ? true : throw new AssertionError($"Regex pattern did not match.\n Regex: {Builtins.repr(pattern)}\n Input: {Builtins.repr(Builtins.str(value))}");
        public override string ToString() => value == null ? "<ExceptionInfo for raises contextmanager>" : $"<ExceptionInfo {Builtins.PyTypeName(((object)value).GetType())}({Builtins.repr(Builtins.str(value))}) tblen=1>";
    }

    /// <summary>with pytest.raises(E, match=...): the block must raise E (whose str matches the pattern).</summary>
    internal sealed class PyRaises
    {
        readonly Type[] _types;
        readonly string? _match;
        readonly ExceptionInfo _info = new ExceptionInfo();
        public PyRaises(Type[] types, string? match) { _types = types; _match = match; }
        public ExceptionInfo __enter__() => _info;
        public bool __exit__(object? type, object? exc, object? tb)
        {
            if (exc == null) throw new TestFailed($"DID NOT RAISE {string.Join(" or ", _types.Select(t => $"<class '{PythonName(t)}'>"))}");
            if (!_types.Any(t => t.IsInstanceOfType(exc))) return false;
            _info.value = exc;
            _info.type = exc.GetType();
            if (_match != null) _info.match(_match);
            return true;
        }
        static string PythonName(Type t) => PytestRunner.ExceptionName(t);
    }

    /// <summary>pytest.approx(expected): equal to numbers (and lists/tuples/dicts of numbers) within a tolerance.</summary>
    internal sealed class PyApprox : IPyRepr
    {
        readonly object? _expected;
        readonly double _rel, _abs;
        public PyApprox(object? expected, double? rel, double? abs) { _expected = expected; _rel = rel ?? 1e-6; _abs = abs ?? 1e-12; }
        internal static bool Number(object? o, out double d)
        {
            switch (o)
            {
                case double x: d = x; return true;
                case float x: d = x; return true;
                case long x: d = x; return true;
                case int x: d = x; return true;
                case System.Numerics.BigInteger x: d = (double)x; return true;
                default: d = 0; return false;
            }
        }
                bool Close(double a, double e) => a == e || Math.Abs(a - e) <= Math.Max(_rel * Math.Abs(e), _abs);
        bool Matches(object? actual, object? expected)
        {
            if (PyApprox.Number(expected, out var e) && PyApprox.Number(actual, out var a)) return Close(a, e);
            if (expected is IDictionary ed && actual is IDictionary ad)
                return ed.Count == ad.Count && ed.Keys.Cast<object>().All(k => ad.Contains(k) && Matches(ad[k], ed[k]));
            if (expected is IEnumerable el && !(expected is string) && actual is IEnumerable al && !(actual is string))
            {
                var xs = el.Cast<object?>().ToList(); var ys = al.Cast<object?>().ToList();
                return xs.Count == ys.Count && xs.Zip(ys, (x, y) => Matches(y, x)).All(b => b);
            }
            return Builtins.eq(actual, expected);
        }
        public override bool Equals(object? obj) => Matches(obj is PyApprox ? null : obj, _expected);
        public override int GetHashCode() => 0;
        public static bool operator ==(PyApprox a, object? b) => a.Equals(b);
        public static bool operator !=(PyApprox a, object? b) => !a.Equals(b);
        public static bool operator ==(object? a, PyApprox b) => b.Equals(a);
        public static bool operator !=(object? a, PyApprox b) => !b.Equals(a);
        public static bool operator ==(double a, PyApprox b) => b.Equals(a);
        public static bool operator !=(double a, PyApprox b) => !b.Equals(a);
        public static bool operator ==(PyApprox a, double b) => a.Equals(b);
        public static bool operator !=(PyApprox a, double b) => !a.Equals(b);
        public static bool operator ==(long a, PyApprox b) => b.Equals(a);
        public static bool operator !=(long a, PyApprox b) => !b.Equals(a);
        public string __repr__() => PyApprox.Number(_expected, out var e) ? $"{Builtins.repr(e)} ± {Math.Max(_rel * Math.Abs(e), _abs):0.0e+00}" : $"approx({Builtins.repr(_expected)})";
        public override string ToString() => __repr__();
    }

    /// <summary>The capsys fixture: what the test printed, read with readouterr().</summary>
    internal sealed class CapSys
    {
        readonly System.IO.StringWriter _out = new System.IO.StringWriter(), _err = new System.IO.StringWriter();
        readonly System.IO.TextWriter _savedOut, _savedErr;
        public CapSys() { _savedOut = Console.Out; _savedErr = Console.Error; Console.SetOut(_out); Console.SetError(_err); }
        public CaptureResult readouterr()
        {
            Console.Out.Flush(); Console.Error.Flush();
            var r = new CaptureResult(_out.ToString(), _err.ToString());
            _out.GetStringBuilder().Clear(); _err.GetStringBuilder().Clear();
            return r;
        }
        internal void Restore() { Console.SetOut(_savedOut); Console.SetError(_savedErr); }
    }

    internal sealed class CaptureResult : IPyRepr
    {
        public readonly string @out, err;
        public CaptureResult(string o, string e) { @out = o; err = e; }
        public string __repr__() => $"CaptureResult(out={Builtins.repr(@out)}, err={Builtins.repr(err)})";
        public override string ToString() => __repr__();
    }

    /// <summary>Runs a test module's tests the way pytest does and prints pytest's report.</summary>
    internal static class PytestRunner
    {
        sealed class TestCase
        {
            public string Id = "";
            public Func<object?[], object?> Call = _ => null;
            public string[] Params = Array.Empty<string>();
            public Dictionary<string, object?> Given = new Dictionary<string, object?>();
            public PyTestMarks? Marks;
        }

        public static string ExceptionName(Type t) => t.Name switch
        {
            "ArgumentException" => "ValueError",
            "InvalidCastException" => "TypeError",
            "KeyNotFoundException" => "KeyError",
            "IndexOutOfRangeException" or "ArgumentOutOfRangeException" => "IndexError",
            "DivideByZeroException" => "ZeroDivisionError",
            "MissingMemberException" => "AttributeError",
            "OverflowException" => "OverflowError",
            "NotImplementedException" => "NotImplementedError",
            "FileNotFoundException" => "FileNotFoundError",
            "InvalidOperationException" => "RuntimeError",
            "NullReferenceException" => "AttributeError",
            "TestFailed" => "Failed",
            _ => t.Name,
        };

        public static void Run(Type module, string file, (string Name, object? Value)[] entries)
        {
            var sw = Stopwatch.StartNew();
            var fixtures = new Dictionary<string, PyFixture>();
            foreach (var (name, value) in entries)
                if (value is PyFixture fx) fixtures[name] = fx;

            var tests = new List<TestCase>();
            foreach (var (name, value) in entries)
                if (name.StartsWith("test") || name.StartsWith("Test")) Collect(module, name, value, tests);

            var moduleCache = new Dictionary<string, object?>();
            var moduleTeardown = new List<IEnumerator>();
            var report = new System.Text.StringBuilder();
            var failures = new List<(string Id, Exception Error)>();
            var output = new Dictionary<string, string>();
            int passed = 0, failed = 0, skipped = 0, xfailed = 0, xpassed = 0;
            var savedOut = Console.Out;
            savedOut.Write(file + " ");
            foreach (var t in tests)
            {
                string outcome;
                var teardown = new List<IEnumerator>();
                CapSys? capsys = null;
                if (t.Marks?.SkipReason != null) { skipped++; savedOut.Write("s"); continue; }
                // what a test prints is captured, and shown only when it fails (pytest's default)
                var captured = new System.IO.StringWriter();
                Console.SetOut(captured);
                try
                {
                    var functionCache = new Dictionary<string, object?>();
                    foreach (var auto in fixtures.Where(kv => kv.Value.Autouse)) Resolve(auto.Key, fixtures, functionCache, moduleCache, teardown, moduleTeardown, ref capsys, new HashSet<string>());
                    var args = t.Params.Select(p => t.Given.TryGetValue(p, out var v) ? v
                        : Resolve(p, fixtures, functionCache, moduleCache, teardown, moduleTeardown, ref capsys, new HashSet<string>())).ToArray();
                    t.Call(args);
                    outcome = t.Marks?.Xfail == true ? "X" : ".";
                }
                catch (Exception e)
                {
                    e = Unwrap(e);
                    outcome = e is TestSkipped ? "s" : t.Marks?.Xfail == true ? "x" : "F";
                    if (outcome == "F") failures.Add((t.Id, e));
                }
                finally
                {
                    capsys?.Restore();
                    for (int i = teardown.Count - 1; i >= 0; i--) Finish(teardown[i]);
                    Console.SetOut(savedOut);
                }
                if (outcome == "F" && captured.ToString().Length > 0) output[t.Id] = captured.ToString();
                switch (outcome)
                {
                    case ".": passed++; break;
                    case "F": failed++; break;
                    case "s": skipped++; break;
                    case "x": xfailed++; break;
                    case "X": xpassed++; break;
                }
                savedOut.Write(outcome);
            }
            for (int i = moduleTeardown.Count - 1; i >= 0; i--) Finish(moduleTeardown[i]);
            savedOut.WriteLine(tests.Count == 0 ? "" : " [100%]");

            if (failures.Count > 0)
            {
                Console.WriteLine(Banner("FAILURES", '='));
                foreach (var (id, e) in failures)
                {
                    Console.WriteLine(Banner(id, '_'));
                    Console.WriteLine();
                    var (path, line) = SourceOf(e);
                    if (path != null && line > 0 && System.IO.File.Exists(path))
                    {
                        var lines = System.IO.File.ReadAllLines(path);
                        if (line <= lines.Length) Console.WriteLine(">   " + lines[line - 1].Trim());
                    }
                    Console.WriteLine($"E   {Describe(e)}");
                    Console.WriteLine();
                    if (path != null) Console.WriteLine($"{System.IO.Path.GetFileName(path)}:{line}: {ExceptionName(e.GetType())}");
                    if (output.TryGetValue(id, out var printed))
                    {
                        Console.WriteLine(Banner("Captured stdout call", '-'));
                        Console.Write(printed);
                    }
                }
                Console.WriteLine(Banner("short test summary info", '='));
                foreach (var (id, e) in failures) Console.WriteLine($"FAILED {file}::{id} - {Describe(e)}");
            }
            var parts = new List<string>();
            if (failed > 0) parts.Add($"{failed} failed");
            if (passed > 0) parts.Add($"{passed} passed");
            if (skipped > 0) parts.Add($"{skipped} skipped");
            if (xfailed > 0) parts.Add($"{xfailed} xfailed");
            if (xpassed > 0) parts.Add($"{xpassed} xpassed");
            if (parts.Count == 0) parts.Add("no tests ran");
            Console.WriteLine(Banner($"{string.Join(", ", parts)} in {sw.Elapsed.TotalSeconds:0.00}s", '='));
            Environment.ExitCode = failed > 0 ? 1 : tests.Count == 0 ? 5 : 0;
        }

        static string Banner(string text, char c)
        {
            text = " " + text + " ";
            int left = Math.Max(1, (80 - text.Length) / 2), right = Math.Max(1, 80 - text.Length - left);
            return new string(c, left) + text + new string(c, right);
        }

        static string Describe(Exception e)
        {
            string name = ExceptionName(e.GetType());
            if (e is AssertionError ae && ae.Message == "assertion failed") return ae.Detail ?? "assert False";
            string msg = Builtins.ExceptionText(e);
            return msg.Length == 0 ? name : $"{name}: {msg}";
        }

        static (string?, int) SourceOf(Exception e)
        {
            foreach (var frame in new StackTrace(e, true).GetFrames() ?? Array.Empty<StackFrame>())
                if (frame.GetFileName() is string f && f.EndsWith(".ty")) return (f, frame.GetFileLineNumber());
            return (null, 0);
        }

        static Exception Unwrap(Exception e)
        {
            while (e is TargetInvocationException && e.InnerException != null) e = e.InnerException;
            return e;
        }

        static void Finish(IEnumerator it)
        {
            try { it.MoveNext(); } catch { }
            (it as IDisposable)?.Dispose();
        }

        static object? Resolve(string name, Dictionary<string, PyFixture> fixtures, Dictionary<string, object?> functionCache, Dictionary<string, object?> moduleCache,
                               List<IEnumerator> teardown, List<IEnumerator> moduleTeardown, ref CapSys? capsys, HashSet<string> resolving)
        {
            if (functionCache.TryGetValue(name, out var cached) || moduleCache.TryGetValue(name, out cached)) return cached;
            switch (name)
            {
                case "tmp_path":
                {
                    var dir = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "typhon-test-" + Guid.NewGuid().ToString("N").Substring(0, 8));
                    System.IO.Directory.CreateDirectory(dir);
                    return functionCache[name] = Typhon.Stdlib.pathlib.Path(dir);
                }
                case "capsys":
                    capsys = new CapSys();
                    return functionCache[name] = capsys;
            }
            if (!fixtures.TryGetValue(name, out var fx)) throw new TestFailed($"fixture '{name}' not found");
            if (!resolving.Add(name)) throw new TestFailed($"recursive dependency involving fixture '{name}' detected");
            var names = ParamNames(fx.Func);
            var args = new object?[names.Length];
            for (int i = 0; i < names.Length; i++) args[i] = Resolve(names[i], fixtures, functionCache, moduleCache, teardown, moduleTeardown, ref capsys, resolving);
            object? value = Builtins.__invoke(fx.Func, args);
            // a yield fixture: the value it yields; the rest of it runs after the test (or the module)
            if (value is IEnumerable gen && !(value is string) && !(value is IList) && !(value is IDictionary) && IsGenerator(value))
            {
                var it = gen.GetEnumerator();
                if (!it.MoveNext()) throw new TestFailed($"fixture '{name}' did not yield a value");
                value = it.Current;
                (fx.Scope == "function" ? teardown : moduleTeardown).Add(it);
            }
            (fx.Scope == "function" ? functionCache : moduleCache)[name] = value;
            return value;
        }

        static bool IsGenerator(object v)
        {
            var t = v.GetType();
            return t.Name.Contains("PyGenerator") || t.IsDefined(typeof(System.Runtime.CompilerServices.CompilerGeneratedAttribute), false) ||
                   t.GetInterfaces().Contains(typeof(IEnumerator));
        }

        /// <summary>A callable's parameter names (a Typhon function value's, a method's, a marked test's function's).</summary>
        static string[] ParamNames(object? f) => f switch
        {
            PyTestMarks m => ParamNames(m.Func),
            PyFunction pf => pf.__param_names__ ?? Array.Empty<string>(),
            Delegate d => d.Method.GetParameters().Select(p => p.Name ?? "").ToArray(),
            _ => Array.Empty<string>(),
        };

        static void Collect(Type module, string name, object? value, List<TestCase> tests)
        {
            const BindingFlags S = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static;
            var nested = module.GetNestedType(name, BindingFlags.Public | BindingFlags.NonPublic);
            if (nested != null)
            {
                if (nested.GetConstructor(Type.EmptyTypes) == null) return;
                foreach (var m in nested.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly).Where(m => m.Name.StartsWith("test")).OrderBy(m => m.MetadataToken))
                {
                    var marks = nested.GetField("__decorated_" + m.Name, S)?.GetValue(null) as PyTestMarks;
                    var method = m;
                    var ps = method.GetParameters().Select(p => p.Name ?? "").ToArray();
                    Expand(tests, $"{name}::{m.Name}", ps, a => Invoke(method, Activator.CreateInstance(nested), a), marks);
                }
                return;
            }
            if (value is PyFixture) return;
            if (value != null)
            {
                var marks = value as PyTestMarks;
                Expand(tests, name, ParamNames(value), a => Builtins.__invoke(value, a), marks);
                return;
            }
            var methods = module.GetMethods(S).Where(m => m.Name == name).ToList();
            if (methods.Count == 0) return;
            // the test's own version (a function inferred with typed overloads keeps a dynamic one for calls like this)
            var target = methods.OrderByDescending(m => m.GetParameters().Count(p => p.ParameterType == typeof(object))).First();
            Expand(tests, name, target.GetParameters().Select(p => p.Name ?? "").ToArray(), a => Invoke(target, null, a), null);
        }

        static object? Invoke(MethodInfo m, object? self, object?[] args)
        {
            var ps = m.GetParameters();
            var call = new object?[ps.Length];
            for (int i = 0; i < ps.Length; i++)
                call[i] = i < args.Length ? (args[i] == null || ps[i].ParameterType.IsInstanceOfType(args[i]) ? args[i] : Convert.ChangeType(args[i], ps[i].ParameterType)) : ps[i].DefaultValue;
            return m.Invoke(self, call);
        }

        static void Expand(List<TestCase> tests, string id, string[] ps, Func<object?[], object?> call, PyTestMarks? marks)
        {
            var sets = new List<(string Suffix, Dictionary<string, object?> Given)> { ("", new Dictionary<string, object?>()) };
            if (marks != null)
                foreach (var (names, rows, ids) in Enumerable.Reverse(marks.Parametrize))
                {
                    var next = new List<(string, Dictionary<string, object?>)>();
                    foreach (var (suffix, given) in sets)
                        for (int r = 0; r < rows.Count; r++)
                        {
                            var g = new Dictionary<string, object?>(given);
                            for (int k = 0; k < names.Length; k++) g[names[k]] = rows[r][k];
                            string rowId = ids != null && r < ids.Count ? ids[r] : string.Join("-", rows[r].Select((v, k) => IdOf(v, names[k], r)));
                            next.Add((suffix.Length == 0 ? rowId : suffix + "-" + rowId, g));
                        }
                    sets = next;
                }
            foreach (var (suffix, given) in sets)
                tests.Add(new TestCase { Id = suffix.Length == 0 ? id : $"{id}[{suffix}]", Call = call, Params = ps, Given = given, Marks = marks });
        }

        static string IdOf(object? v, string name, int row) => v switch
        {
            null => "None",
            bool b => b ? "True" : "False",
            string s => s,
            long or int or double => Builtins.str(v),
            _ => name + row,
        };
    }
}

namespace Typhon.Stdlib
{
    using System;
    using System.Collections;
    using System.Collections.Generic;
    using System.Linq;
    using Typhon.Runtime;

    /// <summary>pytest's API for test modules; `typhon test` runs the tests.</summary>
    internal static class pytest
    {
        /// <summary>@pytest.fixture or @pytest.fixture(scope="module", autouse=True).</summary>
        public static dynamic fixture(object? func = null, string scope = "function", bool autouse = false)
        {
            if (func != null) return new PyFixture(func, scope, autouse);
            return new PyClosure("fixture", (a, kw) => new PyFixture(a[0], scope, autouse));
        }

        public static PyRaises raises(object expected_exception, string? match = null) =>
            new PyRaises(expected_exception is Type t ? new[] { t } : ((IEnumerable)expected_exception).Cast<Type>().ToArray(), match);

        public static PyApprox approx(object? expected, double? rel = null, double? abs = null) => new PyApprox(expected, rel, abs);

        public static void fail(string reason = "") => throw new TestFailed(reason);
        public static void skip(string reason = "") => throw new TestSkipped(reason);

        /// <summary>pytest.mark: marks on tests.</summary>
        public static class mark
        {
            /// <summary>@pytest.mark.parametrize("a, b", [(1, 2), (3, 4)]): the test runs once per row.</summary>
            public static dynamic parametrize(string argnames, object? argvalues, object? ids = null)
            {
                var names = argnames.Split(',').Select(n => n.Trim()).Where(n => n.Length > 0).ToArray();
                var rows = new List<object?[]>();
                foreach (var row in (IEnumerable)argvalues!)
                    rows.Add(names.Length == 1 ? new[] { row } : Builtins.__iter_dyn(row).Cast<object?>().ToArray());
                var idList = ids is IEnumerable idv && !(ids is string) ? idv.Cast<object?>().Select(Builtins.str).ToList() : null;
                return new PyClosure("parametrize", (a, kw) =>
                {
                    var marks = PyTestMarks.Of(a[0]);
                    marks.Parametrize.Add((names, rows, idList));
                    return marks;
                });
            }

            public static dynamic skip(object? func = null, string reason = "")
            {
                if (func != null && !(func is string)) { var m = PyTestMarks.Of(func); m.SkipReason = reason; return m; }
                string why = func as string ?? reason;
                return new PyClosure("skip", (a, kw) => { var m = PyTestMarks.Of(a[0]); m.SkipReason = why; return m; });
            }

            public static dynamic skipif(bool condition, string reason = "") =>
                new PyClosure("skipif", (a, kw) => { var m = PyTestMarks.Of(a[0]); if (condition) m.SkipReason = reason; return m; });

            public static dynamic xfail(object? func = null, string reason = "")
            {
                if (func != null && !(func is string)) { var m = PyTestMarks.Of(func); m.Xfail = true; m.XfailReason = reason; return m; }
                string why = func as string ?? reason;
                return new PyClosure("xfail", (a, kw) => { var m = PyTestMarks.Of(a[0]); m.Xfail = true; m.XfailReason = why; return m; });
            }
        }

        /// <summary>After a test module's body: runs its tests when `typhon test` started it (like pytest; `typhon run` only runs the body).</summary>
        public static void __run_module(Type module, string file, (string Name, object? Value)[] entries)
        {
            if (Environment.GetEnvironmentVariable("TYPHON_TEST") != "1") return;
            PytestRunner.Run(module, file, entries);
        }
    }
}
